UPDATE Building_YieldChanges SET Yield=Yield+2 WHERE rowid=
 (SELECT MIN(rowid) FROM Building_YieldChanges WHERE BuildingType='BUILDING_PALEO_NATURAL_HISTORY_MUSEUM' AND YieldType='YIELD_SCIENCE');
INSERT INTO Building_YieldChanges(BuildingType,YieldType,Yield)
 SELECT 'BUILDING_PALEO_NATURAL_HISTORY_MUSEUM','YIELD_SCIENCE',2 WHERE NOT EXISTS
 (SELECT 1 FROM Building_YieldChanges WHERE BuildingType='BUILDING_PALEO_NATURAL_HISTORY_MUSEUM' AND YieldType='YIELD_SCIENCE');
UPDATE Building_YieldChanges SET Yield=Yield+1 WHERE rowid=
 (SELECT MIN(rowid) FROM Building_YieldChanges WHERE BuildingType='BUILDING_PALEO_NATURAL_HISTORY_MUSEUM' AND YieldType='YIELD_CULTURE');
INSERT INTO Building_YieldChanges(BuildingType,YieldType,Yield)
